def semver_sort(versions):
    def parse_version(version):
        # Separate build metadata
        if '+' in version:
            version, build = version.rsplit('+', 1)
        else:
            build = ''

        # Separate pre-release
        if '-' in version:
            base, prerelease = version.split('-', 1)
        else:
            base = version
            prerelease = None

        # Parse base version (MAJOR.MINOR.PATCH)
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease is not None:
            prerelease_identifiers = prerelease.split('.')
            # Convert numeric identifiers to integers for comparison
            parsed_identifiers = []
            for ident in prerelease_identifiers:
                if ident.isdigit():
                    parsed_identifiers.append((0, int(ident)))
                else:
                    parsed_identifiers.append((1, ident))
            prerelease_identifiers = parsed_identifiers

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(version):
        major, minor, patch, prerelease_identifiers = parse_version(version)

        # For sorting: version without pre-release sorts after version with pre-release
        # We use a tuple: (major, minor, patch, has_prerelease, prerelease_identifiers)
        # has_prerelease is False (0) if prerelease exists, True (1) if not
        if prerelease_identifiers:
            return (major, minor, patch, 0, prerelease_identifiers)
        else:
            return (major, minor, patch, 1)

    # Sort using stable sort to preserve input order for equal precedence
    return sorted(versions, key=compare_key)

